def mutation_op_forge_ast_mutate(lines, funcs, target_name):
    if not lines or len(lines) < 4:
        return lines
    r = list(lines)
    try:
        tree = ast.parse('\n'.join(r))
        for n in ast.walk(tree):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)) and random.random() < 0.4:
                n.value = n.value + random.choice([1, -1, 2, -2, 0.5])
            if isinstance(n, ast.Name) and n.id in ('score','gen','rate') and random.random() < 0.3:
                n.id = n.id + '_fm'
        ast.fix_missing_locations(tree)
        r = ast.unparse(tree).split('\n')
    except:
        pass
    return r

