custom_mutation_ops.mutation_op_forge_ast_mutate:
def mutation_op_forge_ast_mutate(lines, funcs, target_name):
    if not lines or len(lines) < 4:
        return lines
    r = list(lines)
    try:
        tree = ast.parse('\n'.join(r))
        for n in ast.walk(tree):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)) and random.random() < 0.4:
                n.value = n.value + random.choice([1, -1, 2, -2, 0.5])
            if isinstance(n, ast.Name) and n.id in ('score','gen','rate') and random.random() < 0.3:
                n.id = n.id + '_fm'
        ast.fix_missing_locations(tree)
        r = ast.unparse(tree).split('\n')
    except:
        pass
    return r

custom_mutation_ops.mutation_op_forge_cross_function_inject:
def mutation_op_forge_cross_function_inject(lines, funcs, target_name):
    if not lines or len(lines) < 4:
        return lines
    r = list(lines)
    available = [n for n in funcs if n != target_name]
    if available:
        src = random.choice(available)
        _, body = funcs[src]
        if body:
            body_lines = [l for l in body.split('\n') if l.strip()]
            if body_lines:
                r.insert(random.randrange(len(r)), '    # forge:cross-inject from ' + src + '\n')
                r.insert(random.randrange(len(r)), '    ' + random.choice(body_lines) + '\n')
    return r

